import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

fused_op_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ inline float gelu_approx(float x) {
    // Approximate GELU
    return 0.5f * x * (1.0f + erff(x * 0.70710678f));
}

__global__ void fused_op_kernel(const float* __restrict__ input,
                                const float* __restrict__ bias,
                                float* __restrict__ output,
                                int B, int C, int H, int W,
                                int bias_size) {
    int b = blockIdx.x;
    int w = threadIdx.x;
    if (b < B && w < W) {
        // Compute min along channel -> sum along height -> gelu -> add bias
        float accum = 0.0f;
        for (int h = 0; h < H; h++) {
            float min_val = input[(b * C * H + 0 * H + h) * W + w];
            for (int c = 1; c < C; c++) {
                float val = input[(b * C * H + c * H + h) * W + w];
                min_val = fminf(min_val, val);
            }
            accum += min_val;
        }
        float val = gelu_approx(accum);

        // Add bias based on its size (for demonstration)
        float b_val = 0.0f;
        // If bias_size == W, we assume it's (W,) shape
        // If bias_size == 1, we assume a scalar bias
        if (bias_size == W) {
            b_val = bias[w];
        } else if (bias_size == 1) {
            b_val = bias[0];
        }

        // Write to output: shape (B, 1, 1, W)
        output[(b * 1 * 1) * W + w] = val + b_val;
    }
}

torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor bias) {
    const auto B = input.size(0);
    const auto C = input.size(1);
    const auto H = input.size(2);
    const auto W = input.size(3);

    auto output = torch::zeros({B, 1, 1, W}, input.options());
    int bias_size = bias.numel();

    const int blockSize = W;
    const int gridSize = B;

    fused_op_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, H, W,
        bias_size
    );

    return output;
}
"""

fused_op_cpp_source = "torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor bias);"

fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_op_cpp_source,
    cuda_sources=fused_op_source,
    functions=["fused_op_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that uses a custom CUDA kernel to fuse min, sum, GELU, and bias addition
    after a ConvTranspose2d.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride, padding, output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_op = fused_op

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_op.fused_op_cuda(x, self.bias)
        return x
